import{_ as t,o as a,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator 2023-03-07","description":"","frontmatter":{"title":"Ceph Orchestrator 2023-03-07","date":"2023-03-07T00:00:00.000Z","updated":"2023-03-08T00:00:00.000Z","tags":["分布式存储","Ceph","安全证书管理","Kubernetes","Secret store"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_2023-03-07.md","filePath":"posts/2023/Ceph_Orchestrator_2023-03-07.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Orchestrator_2023-03-07.md"};function o(s,e,n,h,c,u){return a(),r("div",null,[...e[0]||(e[0]=[l('<p>会议纪要</p><h4 id="会议主题-证书管理与安全存储讨论" tabindex="-1">会议主题：证书管理与安全存储讨论 <a class="header-anchor" href="#会议主题-证书管理与安全存储讨论" aria-label="Permalink to &quot;会议主题：证书管理与安全存储讨论&quot;">​</a></h4><h4 id="参会人员-未列出" tabindex="-1">参会人员：[未列出] <a class="header-anchor" href="#参会人员-未列出" aria-label="Permalink to &quot;参会人员：[未列出]&quot;">​</a></h4><h4 id="会议时间-未列出" tabindex="-1">会议时间：[未列出] <a class="header-anchor" href="#会议时间-未列出" aria-label="Permalink to &quot;会议时间：[未列出]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>证书管理现状分析</strong></p><ul><li>当前系统中管理的证书包括RGB前端证书和Grafana证书等。</li><li>证书存储在不同位置，如配置资源或RSW规范中。</li></ul></li><li><p><strong>证书管理需求</strong></p><ul><li>需要跟踪和管理所有证书，尤其关注其到期时间。</li><li>目标是监控证书到期状态，并在接近到期时发出健康警告。</li></ul></li><li><p><strong>安全存储方案讨论</strong></p><ul><li>提议引入统一的Secret store来存储所有安全相关数据，如证书、SSH密钥和密码。</li><li>该Secret store类似于Kubernetes Secrets，提供通用机制管理敏感数据。</li></ul></li><li><p><strong>实施计划与挑战</strong></p><ul><li>需进行一次大规模迁移，将现有证书和其他敏感数据迁移到新的Secret store中。</li><li>需考虑向后兼容性，确保迁移过程中不影响现有系统运行。</li></ul></li><li><p><strong>未来扩展性</strong></p><ul><li>统一的Secret store便于未来与Vault等其他安全工具集成。</li><li>提供结构化方式管理和访问敏感数据，增强系统安全性和可维护性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>创建统一的Secret store，用于集中管理所有安全相关数据。</li><li>进行一次大规模迁移，将现有证书和其他敏感数据迁移到新的Secret store中。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>创建跟踪器记录和管理证书管理工作。</li><li>设计和实施Secret store，确保其安全性和易用性。</li><li>完成数据迁移，并更新相关代码以使用新的Secret store。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论TLS证书管理和安全存储方案后结束，计划下周继续讨论相关细节。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的“Secret store”和“Kubernetes Secrets”是计算机科学领域中的专业术语，分别指代集中存储敏感数据的地方和Kubernetes系统中用于管理敏感数据的一种机制。</li></ul>',14)])])}const _=t(i,[["render",o]]);export{p as __pageData,_ as default};
